9	/**
10	 * Rejects a create-owner request that shares a household with an existing owner: same
11	 * last name and same address, each compared case-insensitively with runs of whitespace
12	 * collapsed to a single space. Runs before {@link BuildOwner}. A collision is rejected
13	 * 409 via {@link DuplicateHouseholdException}, unless the request opts in with
14	 * {@code sharesHousehold} set true.
15	 */
16	public class RejectDuplicateHousehold {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateHouseholdException {
20	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
21	            return;
22	        }
23	        String lastName = normalize(request.getLastName());
24	        String address = normalize(request.getAddress());
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (normalize(existing.getLastName()).equals(lastName)
27	                    && normalize(existing.getAddress()).equals(address)) {
28	                throw new DuplicateHouseholdException(
29	                        "Another owner with the same last name and address already exists");
30	            }
31	        }
32	    }
33	
34	    private static String normalize(String value) {
35	        if (value == null) {
36	            return "";
37	        }
38	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
39	    }
40	}
