7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code <LAST3>-<NNNN>} where
9	 * LAST3 is the upper-cased first three letters of the last name and NNNN is a global
10	 * 4-digit zero-padded sequence equal to one more than the current number of owners
11	 * (e.g. {@code SMI-0007}).
12	 *
13	 * <p>Runs after {@code BuildOwner} (so the owner exists) but before {@code SaveOwner}
14	 * (so the owner being created is not yet counted), mutating the owner in place.
15	 */
16	public class AssignCustomerCode {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        int sequence = ownerRepository.findAll().size() + 1;
20	        String lastName = owner.getLastName();
21	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
22	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
23	    }
24	}
