10	/**
11	 * Maps a YAML {@code authorize:} denial to 403, mirroring how Spring's own
12	 * ExceptionTranslationFilter would translate an AccessDeniedException on the servlet
13	 * filter chain - required because OfficeFloor evaluates {@code authorize:} inline in the
14	 * function pipeline rather than via that filter.
15	 */
16	public class ForbiddenExceptionHandler {
17	
18	    public void handle(@Parameter AuthorizationDeniedException ex,
19	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
20	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.FORBIDDEN,
21	                "You do not have permission to access this resource");
22	        response.send(ResponseEntity.status(HttpStatus.FORBIDDEN).body(detail));
23	    }
24	}
